// Доля НАСЫЩАЕТСЯ: «все мои внешние связи межтрадиционные» — частое и
// настоящее состояние, и равенство таких концепций честно. Но порядок
// ВНУТРИ равенства не должен решаться порядком в массиве, поэтому
// добор — по числу межтрадиционных связей: при равной доле выше тот,
// за кем больше свидетельств.
const results = nodes.map(n => {
  const metric = traditionBridgingIndex(n.id);
  return { node: n, value: metric.total, details: metric };
}).filter(rankKeep).sort((a, b) => b.value - a.value
          || b.details.crossingLinks - a.details.crossingLinks);
